 if((m=s.match(/^(\d+) item\(s\) should be used before buying more$/)))return lang==='hi'?`और खरीदने से पहले ${m[1]} आइटम उपयोग करें`:`Aur kharidne se pehle ${m[1]} item use karo`;
 if((m=s.match(/^(\d+) products · realistic local catalog$/)))return lang==='hi'?`${m[1]} प्रोडक्ट · रियलिस्टिक लोकल कैटलॉग`:`${m[1]} products · realistic local catalog`;
